#pragma once
//Synthetic CHS/audio placeholders only. No decoder, device or user saves.
static void historyText(Program& p,const std::string& text,int wait=1,int page=1,int style=0){p.push(page);p.push(wait);p.push(style);p.push(0);p.string(text);p.op(0x140);}
static void historyVoice(Program& p,const std::string& name,bool variant=false){p.push(0);p.string(name);p.op(variant?0x1a8:0x1a0);}
static void historyVoiceNull(Program& p){p.push(0);p.push(0);p.op(0x1a0);}
static std::string historyList(const std::string& s){auto at=s.find("\"history\":");check(at!=std::string::npos,"history list exists");at+=10;return s.substr(at,s.find(",\"historyRevision\":",at)-at);}
static std::string historyAudio(const std::string& s){auto at=s.find("\"audio\":");check(at!=std::string::npos,"audio list exists");return s.substr(at,s.find(",\"history\":",at)-at);}
static std::string historyRow(const std::string& s,size_t index){auto list=historyList(s);auto at=list.find("{\"index\":"+std::to_string(index)+",\"text\":");check(at!=std::string::npos,"history row exists");auto end=list.find("{\"index\":"+std::to_string(index+1)+",\"text\":",at+1);return list.substr(at,end==std::string::npos?list.size()-at:end-at);}
static std::string historyTokenValue(const std::string& s,const std::string& key){auto at=s.find("\""+key+"\":\"");check(at!=std::string::npos,"history token exists");at+=key.size()+4;return s.substr(at,s.find('"',at)-at);}
static std::string replayObject(const std::string& s){
    auto at=s.find("\"historyReplay\":");check(at!=std::string::npos,"replay field exists");at+=16;
    auto whitespace=[](char c){return c==' '||c=='\t'||c=='\r'||c=='\n';};
    while(at<s.size()&&whitespace(s[at]))++at;
    if(s.compare(at,4,"null")==0){auto end=at+4;while(end<s.size()&&whitespace(s[end]))++end;check(end==s.size()||s[end]==','||s[end]=='}',"replay null literal boundary");return "null";}
    check(at<s.size()&&s[at]=='{',"replay value is object or null");
    const auto start=at;std::vector<char> closing;bool quoted=false,escaped=false;
    for(;at<s.size();++at){const char c=s[at];if(quoted){if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(c=='"')quoted=false;}else if(c=='"')quoted=true;else if(c=='{'||c=='[')closing.push_back(c=='{'?'}':']');else if(c=='}'||c==']'){check(!closing.empty()&&closing.back()==c,"replay nesting boundary");closing.pop_back();if(closing.empty())return s.substr(start,at-start+1);}}
    throw std::runtime_error("Unterminated replay object");
}
static std::string replayPair(const std::string& s){auto replay=replayObject(s);return historyTokenValue(replay,"generation")+" "+historyTokenValue(replay,"id");}
static void historyAsset(Fixture& f,const std::string& name){auto path=f.game/"audio"/(name+".hw.ogg");fs::create_directories(path.parent_path());f.extraFiles.push_back(path);std::ofstream(path,std::ios::binary)<<"not decoded: private history asset placeholder";}
static mahoyo::history::State savedHistory(const mahoyo::save::Document& document){std::string extra(document.hostExtra.begin(),document.hostExtra.end());auto at=extra.find("HISTORYMETA1 ");check(at!=std::string::npos,"WH17 footer exists");std::istringstream input(extra.substr(at));return mahoyo::history::read(input,document.history.size());}
static mahoyo::save::Document withHistory(mahoyo::save::Document document,const mahoyo::history::State& state){std::string extra(document.hostExtra.begin(),document.hostExtra.end());const auto clockFooter=extra.substr(extra.find("WAITBASELINE1 "));extra.resize(extra.find("HISTORYMETA1 "));std::ostringstream out;mahoyo::history::write(out,state,document.history.size());extra+=out.str()+clockFooter;document.hostExtra.assign(extra.begin(),extra.end());return document;}
static void historyHfaVoiceAvailability(){
    const std::string loops="a10_first.hw\t44100\t44100\t1\t0\t0\t44100\n";
    for(bool hfa:{false,true}){
        Program p;historyVoice(p,"a10_first");historyText(p,"VOICE");historyVoice(p,"a11_absent");historyText(p,"MISSING");p.op(0xf4);
        Fixture f(std::move(p),false,{},{},loops);
        if(hfa){std::ofstream marker(f.game/".steam-ready");marker<<"{\"schema\":1}";f.extraFiles.push_back(f.game/".steam-ready");}
        f.command("textSpeed","0");f.command("action","start");auto state=f.command("history");
        check(boolean(historyRow(state,0),"available")==hfa,"raw HFA voice uses prepared archive inventory; unpacked data still requires a file");
        state=f.command("historyReplay",(historyTokenValue(state,"historyRevision")+" 0 1").c_str());
        check((replayObject(state)!="null")==hfa,"HFA-backed history voice can enter the ordinary replay path");
        f.command("historyClose",historyTokenValue(state,"historyRevision").c_str());f.command("advance");state=f.command("history");
        check(!boolean(historyRow(state,1),"available"),"unknown HFA voice names remain unavailable");f.passed=true;
    }
}
